-- WoW Forever: Krol'dok Stronghold (map 3039) rebuilt from live data. Fox (RU) found mobs missing and the bots walking
-- through walls to the bosses. Our 2026_11_11_33 had no live data: placeholder trash (8110000-8110005) and every spot a guess,
-- and the bosses stood far from where live players kill them (Overlord Mugg 600 y off).
-- Source: the EG Link combat logs (Efficient Games, CC BY 4.0, https://efficient.games), client builds 70938 and 70959: the
-- creatures players fought in map 3039, where each one died, its level, health and the spells it cast, and where each boss
-- encounter was pulled. What is real and what is ours:
--  * real: which creatures stand in the stronghold (15 kinds of trash, 6 bosses, Ashka's two wolves), how many of each one run
--    has (the logs' spawn counts), their levels, health multipliers, models, classes and the spells they use; the spot of every
--    live kill (x, y), the boss pull spots.
--  * ours: the height of each spot (the floor of the 3039 navmesh under the live x, y; where the stronghold has two floors there,
--    the one the neighbouring spots stand on), spots for mobs a run has more of than the logs have kill spots (pack mates 3-6 y
--    from a live spot, INFERRED), facing, spell timers (INFERRED), faction 16, gold.
-- A kill spot is where the mob died, so a pack may stand a few yards from where live keeps it.
-- No pack mates within 25 y of a boss: a kill spot there is where the boss fight was fought, and mates piled onto it turned
-- Bossman Toof's two shamans into six (a nine-mob pull that killed the run, kroldok_full af47-1) and gave Twilight Commander
-- Zarmok five extra Grunts. 146 spawns.
-- Krol'dok's own quests (Eye of Mugg, Twilight Mementos, A Token of Vengeance) are not in our world yet, so the quest drops of
-- the Twilight trash (Twilight Mementos 267091/267234) are left out.
-- Spawn guids 48110000-48110199 (the old range, emptied first). Safe to run again.

-- the placeholder trash is gone
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` BETWEEN 8110000 AND 8110005;
DELETE FROM `creature_classic_level` WHERE `entry` BETWEEN 8110000 AND 8110005;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 8110000 AND 8110005;
DELETE FROM `creature_template_difficulty` WHERE `Entry` BETWEEN 8110000 AND 8110005;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 8110000 AND 8110005;

-- the live trash, Ashka's wolves and Tunk (templates from players' caches; faction 16 INFERRED)
DELETE FROM `creature_template` WHERE `entry` IN (257885,257888,257900,258038,258040,258042,258100,258102,258104,258687,262065,262067,259256,259283,259285);
DELETE FROM `creature_template_difficulty` WHERE `Entry` IN (257885,257888,257900,258038,258040,258042,258100,258102,258104,258687,262065,262067,259256,259283,259285);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (257885,257888,257900,258038,258040,258042,258100,258102,258104,258687,262065,262067,259256,259283,259285);

-- levels as live players met them (the combat logs), bosses included
DELETE FROM `creature_classic_level` WHERE `entry` IN (257885,257888,257900,258038,258040,258042,258100,258102,258104,258687,262065,262067,259256,259283,259285,258966,258972,259281,258964,264773,258968);
UPDATE `creature_template_difficulty` SET `HealthModifier` = 4.0, `CreatureDifficultyID` = 348274 WHERE `Entry` = 264773 AND `DifficultyID` = 0;

-- what the trash casts (the spells each one cast in the combat logs; timers INFERRED)
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (257885,257888,258038,258040,258042,258100,258102,258104,258687,259283,259285,262065);

-- spawns: every live kill spot (x, y from the logs, the height from the navmesh), the bosses where live kills them
DELETE FROM `creature` WHERE `guid` BETWEEN 48110000 AND 48110199;
